/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: stagedUpload, seedAlbum, assertDurationWithoutRoomEligibility
 *   Constants: ownedEnvironment, oldEnvironment
 *   Variables: mongo, storage, uploadDirectory
 * Tests
 *   - a single FLAC upload records its exact duration and display duration but is never room eligible
 *   - bulk lossless uploads record exact durations for FLAC, ALAC, AIFF and 24-bit WAV
 * @end-catalog */

/** Lossless Content Manager uploads through the real controllers, MongoDB and S3 SDK: durations recorded, rooms unchanged. */
import assert from 'node:assert/strict';
import { copyFileSync, mkdtempSync, rmSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { after, before, beforeEach, test } from 'node:test';
import { ObjectId } from 'mongodb';

import { catalogReviewMemberDuration } from '../../src/administration/catalog/adminCatalogReviewCapture';
import { bulkUploadAudioTracksWeb, createAudioTrackWeb } from '../../src/controllers/contentManager/mediaController';
import { getDb } from '../../src/infrastructure/database';
import { getS3 } from '../../src/infrastructure/s3';
import { resolveRoomAudioRepresentation } from '../../src/services/media/mediaRepresentationService';
import { startLocalS3 } from '../support/localS3';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';

let mongo: MongoReplicaSetHarness;
let storage: Awaited<ReturnType<typeof startLocalS3>>;
let uploadDirectory: string;
const ownedEnvironment = ['AWS_ENDPOINT_URL_S3', 'AWS_REGION', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'AWS_SESSION_TOKEN', 'S3_BUCKET_NAME', 'S3_MAX_ATTEMPTS'] as const;
const oldEnvironment = Object.fromEntries(ownedEnvironment.map(key => [key, process.env[key]]));

before(async () => {
    mongo = await startMongoReplicaSet('archtree-lossless-upload-duration-test');
    storage = await startLocalS3();
    process.env.AWS_ENDPOINT_URL_S3 = storage.endpoint;
    process.env.AWS_REGION = 'us-east-1';
    process.env.AWS_ACCESS_KEY_ID = 'owned-local-fixture';
    process.env.AWS_SECRET_ACCESS_KEY = 'owned-local-fixture-secret';
    delete process.env.AWS_SESSION_TOKEN;
    process.env.S3_BUCKET_NAME = storage.bucket;
    process.env.S3_MAX_ATTEMPTS = '2';
    uploadDirectory = mkdtempSync(path.join(tmpdir(), 'archtree-lossless-upload-'));
});
beforeEach(async () => {
    for (const collection of ['audioTracks', 'albums', 'users']) await getDb()!.collection(collection).deleteMany({});
    storage.objects.clear(); storage.requests.length = 0;
});
after(async () => {
    getS3().destroy();
    await storage?.stop(); await mongo?.stop();
    if (uploadDirectory) rmSync(uploadDirectory, { recursive: true, force: true });
    for (const key of ownedEnvironment) {
        if (oldEnvironment[key] === undefined) delete process.env[key]; else process.env[key] = oldEnvironment[key];
    }
});

/** Copies a fixture to a temporary path with its extension kept, as the disk upload middleware stores it. */
const stagedUpload = (fixture: string, fieldname: string, mimetype: string): Express.Multer.File => {
    const filePath = path.join(uploadDirectory, `${new ObjectId().toHexString()}-${fixture}`);
    copyFileSync(path.resolve('test/fixtures/room-audio', fixture), filePath);
    return { fieldname, originalname: fixture, encoding: '7bit', mimetype, path: filePath, size: statSync(filePath).size } as Express.Multer.File;
};

const seedAlbum = async () => {
    const owner = new ObjectId(), albumId = new ObjectId();
    await getDb()!.collection('users').insertOne({ _id: owner, role: 'admin', email: `${owner}@example.test` });
    await getDb()!.collection('albums').insertOne({ _id: albumId, title: 'Lossless Album', audioTrackIds: [], lifecycleStatus: 'ready', referenceRevision: 0 });
    return { owner: owner.toHexString(), albumId: albumId.toHexString() };
};

/** The stored track, after asserting that its exact duration is lookup evidence and that it stays outside rooms. */
const assertDurationWithoutRoomEligibility = async (filter: Record<string, unknown>) => {
    const track = await getDb()!.collection('audioTracks').findOne(filter);
    assert.ok(track);
    assert.equal(track.uploadStatus, 'ready');
    assert.equal(track.mediaRepresentation.etag, storage.objects.get(track.s3Key)!.etag);
    assert.deepEqual([track.mediaRepresentation.format, track.mediaRepresentation.seekable, track.mediaRepresentation.durationMs],
        ['unsupported', false, 2000]);
    assert.equal(await resolveRoomAudioRepresentation(track._id.toHexString()), null);
    assert.deepEqual(catalogReviewMemberDuration(track), { durationMs: 2000, durationPrecisionMs: 0 });
    return track;
};

test('a single FLAC upload records its exact duration and display duration but is never room eligible', async () => {
    const { owner, albumId } = await seedAlbum();
    for (const [title, duration, expected] of [['Untyped duration', '', '00:02'], ['Typed duration', '03:00', '03:00']]) {
        let redirect = '';
        await createAudioTrackWeb({
            body: { title, albumId, attributionUnknown: 'true', duration },
            auth: { userId: owner, role: 'admin' },
            files: { mediaFile: [stagedUpload('tone.flac', 'mediaFile', 'audio/flac')] }
        } as any, { redirect: (location: string) => { redirect = location; }, locals: {} } as any, (error?: unknown) => { throw error; });
        assert.match(decodeURIComponent(redirect), /Audio MediaTrack created successfully/);
        const track = await assertDurationWithoutRoomEligibility({ title });
        assert.equal(track.duration, expected, 'A typed duration still wins over the parsed one.');
    }
});

test('bulk lossless uploads record exact durations for FLAC, ALAC, AIFF and 24-bit WAV', async () => {
    const { owner, albumId } = await seedAlbum();
    const files = [['tone.flac', 'audio/flac'], ['tone-covers.flac', 'audio/flac'], ['tone-alac.m4a', 'audio/mp4'],
        ['tone.aiff', 'audio/aiff'], ['tone-24bit.wav', 'audio/wav']] as const;
    const response: { statusCode?: number; body?: any } = {};
    await bulkUploadAudioTracksWeb({
        body: { albumId, attributionUnknown: 'true' },
        auth: { userId: owner, role: 'admin' },
        files: files.map(([name, type]) => stagedUpload(name, 'audioFiles', type)),
        get: (name: string) => name === 'X-Requested-With' ? 'XMLHttpRequest' : undefined
    } as any, {
        status(code: number) { response.statusCode = code; return this; },
        json(body: unknown) { response.body = body; return this; },
        redirect() { throw new Error('The XHR bulk path must answer with JSON.'); },
        locals: {}
    } as any, (error?: unknown) => { throw error; });
    assert.equal(response.statusCode, 200);
    assert.equal(response.body.publishedCount, files.length);
    for (const [name] of files) await assertDurationWithoutRoomEligibility({ originalFileName: name });
});
